-- Archived out-of-scope placeholders are intentionally retained; only active AB entries must be in scope.
SELECT (EXISTS(SELECT 1 FROM public.courses WHERE id='93124428-92f4-48d2-a6dc-e5f9e010248b' AND practice_course_scope='AB') AND EXISTS(SELECT 1 FROM public.courses WHERE id='fccc7540-0c29-43be-8682-ae90ff2534cb' AND practice_course_scope='BC') AND NOT EXISTS(SELECT 1 FROM public.course_outline_entries e JOIN public.course_outline_topics m ON m.entry_id=e.id JOIN public.curriculum_topics t ON t.id=m.topic_id WHERE e.course_id='93124428-92f4-48d2-a6dc-e5f9e010248b' AND NOT e.archived AND t.is_bc_only) AND coalesce((SELECT md5(prosrc)='048a786eb72bf45bc306d9c9a6f1b81f' FROM pg_proc WHERE oid=to_regprocedure('public.link_course_outline_content(uuid,uuid,uuid,bigint,uuid,bigint,boolean)')),false) AND coalesce((SELECT md5(prosrc)='18634ff98184893eb0edac0b3f5ac0cd' FROM pg_proc WHERE oid=to_regprocedure('public.guard_course_outline_bc_only()')),false) AND (SELECT count(*)=2 FROM pg_trigger WHERE tgname IN ('course_outline_topic_bc_only','course_outline_entry_bc_only') AND NOT tgisinternal AND tgenabled='O') AND EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261102000000' AND name='course_lesson_availability' AND cardinality(statements)=1 AND md5(statements[1])='22eb1dced1ac05b37f0dde31e70e8cd1')) AS all_checks_pass;
SELECT jsonb_build_object('courses',(SELECT jsonb_agg(jsonb_build_object('id',id,'title',title,'scope',practice_course_scope,'revision',outline_revision) ORDER BY id) FROM public.courses),'lessons',(SELECT count(*) FROM public.course_lessons),'videos',(SELECT count(*) FROM public.course_videos),'entries',(SELECT count(*) FROM public.course_outline_entries),'archived',(SELECT count(*) FROM public.course_outline_entries WHERE archived),'content_fingerprint',(SELECT md5(jsonb_build_object('lessons',(SELECT jsonb_agg(to_jsonb(l) ORDER BY id) FROM public.course_lessons l),'videos',(SELECT jsonb_agg(to_jsonb(v) ORDER BY id) FROM public.course_videos v),'bindings',(SELECT jsonb_agg(to_jsonb(b) ORDER BY course_id,topic_id) FROM public.course_lesson_courses b))::text))) AS inventory;
